#!/usr/bin/env python3
"""site_numbers.py — the home page's pipeline figures, GENERATED, never hand-typed.

WHY. docs/index.html carried hand-typed numbers ("permit pipeline — 14,659 units", "905 Berkeley building
projects"). They were right on 2026-09-22 and wrong eight days later, and "pipeline" silently included finished
buildings. This script rewrites ONE marked block of index.html:

    <!-- BEGIN site_numbers data="<Explorer Generated stamp>" v4="<v4 sha16>" (generated by ...) -->
    ...
    <!-- END site_numbers -->

TWO SOURCES, deliberately (John, 2026-09-30):
  * COMPLETIONS come from v4, our independent count from raw permits under HCD's definitions: the same figures as the
    Housing Audit page (stage_methods.co_total). The first version took them from the v2 Explorer data, which is
    missing older permits and some unit counts: 3,453 for 2018-25 against the City's 4,022 and v4's 4,126. Each year
    also shows the City's own APR figure (HCD open-data mirror), so the comparison is on the page.
  * NOT YET BUILT and the PROJECT COUNT come from the served Explorer data (docs/explorer_data.js, v4 since 2026-10-01), because only
    v2 has project stages until the cutover to v4.
Both exclude UC Berkeley (its projects are counted in beds, not units).

The BEGIN marker records the Explorer export's "Generated:" stamp; scripts/deploy_gate.py compares it with the
served file, so a new export whose numbers were not regenerated cannot deploy. It also records the v4 sha, for
provenance: re-run this script after every export promotion AND every v4 swap.

Run:  .venv/bin/python scripts/site_numbers.py
"""
import datetime
import html
import json
import os
import re
import sqlite3
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from scripts.v4 import stage_methods as SM  # noqa: E402

DATA = os.path.join(ROOT, 'docs', 'explorer_data.js')
PAGE = os.path.join(ROOT, 'docs', 'index.html')
HCD = os.path.join(ROOT, 'databases', 'hcd_apr_mirror_2026-06-17_fresh.db')
BEGIN_RE = re.compile(r'<!-- BEGIN site_numbers.*?-->.*?<!-- END site_numbers -->', re.S)


def load_explorer():
    s = open(DATA).read()
    stamp = re.search(r'Generated:\s*(.+)', s).group(1).strip()
    return stamp, json.loads(s[s.index('{'):s.rindex('}') + 1])


def figures(d):
    P = [p for p in d['projects'] if not p.get('is_uc_project')]
    todo = [p for p in P if p.get('status') != 'Completed']
    f = dict(projects=len(P), not_built=sum(int(p.get('units') or 0) for p in todo))
    # completions: v4, by the year the permit was finaled
    v4 = SM.ro(SM.LIVE)
    f['v4_sha'] = SM._sha256(SM.LIVE)[:16] if hasattr(SM, '_sha256') else ''
    first, last = v4.execute(
        "SELECT MIN(e.event_date), MAX(e.event_date) FROM events e JOIN event_classifications c USING(event_id) "
        "WHERE e.event_type_code='permit_finaled' AND c.housing_role='new_unit' AND c.is_master=1 "
        "AND COALESCE(c.net_units,0)>0").fetchone()
    years = [str(y) for y in range(int(first[:4]), int(last[:4]) + 1)]
    f['ours'] = {y: SM.co_total(v4, y, y) for y in years}
    f['built'] = sum(f['ours'].values())
    assert f['built'] == SM.co_all_positive(v4), 'per-year completions do not sum to the v4 total'
    f['first_year'], f['latest'] = years[0], last[:10]
    # the City's own annual progress reports (verification target, shown beside ours, never used to compute ours)
    h = sqlite3.connect(f'file:{HCD}?mode=ro', uri=True)
    co = [c for (c,) in h.execute("SELECT name FROM pragma_table_info('table_a2') WHERE name LIKE 'CO\\_%' ESCAPE '\\' "
                                  "AND name <> 'CO_ISSUE_DT1'")]
    city = dict(h.execute(f"SELECT YEAR, SUM({'+'.join(f'COALESCE({c},0)' for c in co)}) FROM table_a2 "
                          "WHERE upper(JURIS_NAME)='BERKELEY' GROUP BY YEAR"))
    f['city'] = {y: int(city[y]) for y in years if city.get(y)}
    base = json.load(open(sorted(__import__('glob').glob(os.path.join(ROOT, 'data', 'baselines', 'reconciliation_baseline_*.json')))[-1]))
    assert sum(f['city'].values()) == base['hard_gated']['city_co_total']['value'], 'City total drifted from the Audit baseline'
    return f


def render(stamp, f):
    yrs = list(f['ours'])
    last = datetime.date.fromisoformat(f['latest'])
    through = f"{last.strftime('%B')} {last.day}"
    def chip(y):
        c = f['city'].get(y)
        city = f'<div style="font-size: .7rem; color: #4a5568;">City {c:,}</div>' if c is not None else \
               '<div style="font-size: .7rem; color: #a0aec0;">City &mdash;</div>'
        return (f'<div style="flex: 0 0 auto; min-width: 3.9rem; padding: .25rem .35rem; background: #eef4fb; border-radius: 6px;">'
                f'<div style="font-size: .75rem; color: #4a5568;">{y}{"*" if y == yrs[-1] else ""}</div>'
                f'<div style="font-weight: 700; font-variant-numeric: tabular-nums;">{f["ours"][y]:,}</div>{city}</div>')
    return f'''<!-- BEGIN site_numbers data="{html.escape(stamp)}" v4="{html.escape(f['v4_sha'])}" (generated by scripts/site_numbers.py — do not hand-edit) -->
  <p style="margin: 0.45rem 0 0.2rem; text-align: center;">
    <a href="explorer.html" class="hero-cta">See Berkeley&rsquo;s permit pipeline &mdash; {f['not_built']:,} units not yet built, {f['built']:,} built since {f['first_year']} &rarr;</a>
  </p>
  <p style="margin: 0.45rem 0 0; text-align: center;">
    <a href="explorer.html?tab=projects" class="hero-cta">See {f['projects']:,} Berkeley building projects &rarr;</a>
  </p>
  <div role="group" aria-label="Units completed each year: our count and the City's" style="max-width: 42rem; margin: 0.7rem auto 0; text-align: center; color: #1a365d;">
    <div style="color: #4a5568; font-size: 0.85rem; margin-bottom: .3rem;">Units completed each year: our count from permits, and the City&rsquo;s report to the state</div>
    <div style="display: flex; flex-wrap: wrap; justify-content: center; gap: .35rem;">{''.join(chip(y) for y in yrs)}</div>
    <div style="margin-top: .3rem; color: #718096; font-size: 0.75rem;">*{yrs[-1]} through {through}; the City&rsquo;s {yrs[-1]} report is not out yet. Why the two differ: <a href="housing-audit.html" style="color: #2b6cb0;">the Housing Audit</a>. Excludes UC Berkeley, counted in beds. &ldquo;Not yet built&rdquo; and the project count come from the Explorer&rsquo;s data, updated {html.escape(stamp[:10])}.</div>
  </div>
  <!-- END site_numbers -->'''


def main():
    stamp, d = load_explorer()
    f = figures(d)
    page = open(PAGE).read()
    assert BEGIN_RE.search(page), 'no site_numbers block in docs/index.html'
    open(PAGE, 'w').write(BEGIN_RE.sub(lambda m: render(stamp, f), page, count=1))
    print(f"site_numbers: {f['projects']:,} projects · {f['not_built']:,} not yet built · {f['built']:,} built since "
          f"{f['first_year']} (v4 {f['v4_sha']}) · ours {f['ours']} · City {f['city']} · explorer {stamp}")


if __name__ == '__main__':
    sys.exit(main())
